/**
 * Passwordless login — request a one-time code. The identifier is an email or
 * username; the code is emailed to the account. Always resolves the same way,
 * so it can't reveal which accounts exist.
 */
export const requestOtp = async (identifier) => {
    const response = await publicFetch(`${API_BASE_URL}/otp-request/`, {
        method: 'POST', body: JSON.stringify({ identifier }),
    });
    return await response.json();
};

/**
 * Verify the one-time code and sign in. On success the server returns an auth
 * token, which we store.
 */
export const verifyOtp = async (identifier, code, remember = true) => {
    const response = await publicFetch(`${API_BASE_URL}/otp-verify/`, {
        method: 'POST', body: JSON.stringify({ identifier, code }),
    });
    const data = await response.json();
    if (data.token) authUtils.login(data.token, data.user, remember);
    return data;
};

/**
 * MPIN sign-in — identifier + 6-digit PIN -> auth token (stored on success).
 * The server rate-limits wrong PINs; a 429 comes back as a thrown error whose
 * message explains the lockout, same as every other failure here.
 */
export const mpinLogin = async (identifier, mpin, remember = true) => {
    const response = await publicFetch(`${API_BASE_URL}/mpin/login/`, {
        method: 'POST', body: JSON.stringify({ identifier, mpin }),
    });
    const data = await response.json();
    if (data.token) authUtils.login(data.token, data.user, remember);
    return data;
};

/** Forgot MPIN — email a one-time reset code. Always resolves generically. */
export const requestMpinReset = async (identifier) => {
    const response = await publicFetch(`${API_BASE_URL}/mpin/reset/`, {
        method: 'POST', body: JSON.stringify({ identifier }),
    });
    return await response.json();
};

/** Finish an MPIN reset — verify the emailed code, set a new PIN, and sign in. */
export const confirmMpinReset = async (identifier, code, mpin, remember = true) => {
    const response = await publicFetch(`${API_BASE_URL}/mpin/reset-confirm/`, {
        method: 'POST', body: JSON.stringify({ identifier, code, mpin }),
    });
    const data = await response.json();
    if (data.token) authUtils.login(data.token, data.user, remember);
    return data;
};

/**
 * Set or change the signed-in user's MPIN.
 *
 * Endpoint: POST /api/users/mpin/set/ (Token auth). Body is { mpin } for a
 * first-time setup and { mpin, current_mpin } to change an existing one — the
 * server requires current_mpin only when the user already has an MPIN. The
 * response echoes { success, has_mpin }; callers use has_mpin to know whether a
 * PIN now exists. If the backend path/shape shifts, keep this function name and
 * adjust only the URL/body here.
 */
export const setMpin = async (mpin, currentMpin) => {
    const body = { mpin };
    if (currentMpin) body.current_mpin = currentMpin;
    const response = await authenticatedFetch(`${API_BASE_URL}/mpin/set/`, {
        method: 'POST', body: JSON.stringify(body),
    });
    return await response.json();
};

// ── Telegram bot linking (Settings → Connect Telegram) ───────────────────────
// The telegram endpoints live under /api/telegram/, a sibling of /api/users/.
const TELEGRAM_BASE_URL = API_BASE_URL.replace(/\/users$/, '/telegram');

/** Current Telegram link state: { linked, telegram_id, username }. */
export const getTelegramLink = async () => {
    const response = await authenticatedFetch(`${TELEGRAM_BASE_URL}/link/`);
    return await response.json();
};

/**
 * Link the signed-in account to a Telegram id. The user gets their id by
 * messaging the bot, which replies with it. Throws with a readable message on
 * a clash (id already linked to another account) or a non-numeric id.
 */
export const linkTelegram = async (telegramId) => {
    const response = await authenticatedFetch(`${TELEGRAM_BASE_URL}/link/`, {
        method: 'POST', body: JSON.stringify({ telegram_id: telegramId }),
    });
    return await response.json();
};

/** Unlink Telegram from the signed-in account. */
export const unlinkTelegram = async () => {
    const response = await authenticatedFetch(`${TELEGRAM_BASE_URL}/link/`, { method: 'DELETE' });
    return await response.json();
};

// ── Shortcut API Keys (for Apple Shortcuts / headless clients) ──────────────

/** List all of the signed-in user's shortcut API keys (masked). */
export const getShortcutKeys = async () => {
    const response = await authenticatedFetch(`${API_BASE_URL}/api-keys/`);
    return await response.json();
};

/** Create a new shortcut API key. Returns the full key once — copy it now. */
export const createShortcutKey = async (label = '') => {
    const response = await authenticatedFetch(`${API_BASE_URL}/api-keys/`, {
        method: 'POST', body: JSON.stringify({ label }),
    });
    return await response.json();
};

/** Revoke (delete) a shortcut API key by id. */
export const deleteShortcutKey = async (id) => {
    const response = await authenticatedFetch(`${API_BASE_URL}/api-keys/${id}/`, {
        method: 'DELETE',
    });
    return await response.json();
};

/** Build a direct URL for downloading a .shortcut file (works on iOS Safari). */
export const shortcutFileUrl = (keyId, type) => {
    const token = authUtils.getToken();
    return `${API_BASE_URL}/api-keys/${keyId}/shortcut/${type}/?token=${encodeURIComponent(token)}`;
};

/**
 * Forgot password — request a reset link (sent to the email out-of-band).
 * Always resolves the same way, so it can't reveal which emails have accounts.
 */
export const requestPasswordReset = async (email) => {
    const response = await publicFetch(`${API_BASE_URL}/password-reset/`, {
        method: 'POST', body: JSON.stringify({ email }),
    });
    return await response.json();
};

/**
 * Finish a reset: set a new password with the uid + token from the emailed link.
 * On success the server returns an auth token, so the user is signed in.
 */
export const confirmPasswordReset = async ({ uid, token, newPassword, newPasswordConfirm }) => {
    const response = await publicFetch(`${API_BASE_URL}/password-reset-confirm/`, {
        method: 'POST',
        body: JSON.stringify({ uid, token, new_password: newPassword, new_password_confirm: newPasswordConfirm }),
    });
    const data = await response.json();
    if (data.token) authUtils.login(data.token, data.user);
    return data;
};

/**
 * Change user password
 * @param {ChangePasswordData} passwordData - Password change data
 * @param {Function} onSuccess - Success callback
 * @param {Function} onError - Error callback
 * @returns {Promise<Object>} Success message
 */
export const changePassword = async (passwordData, onSuccess, onError) => {
    try {
        console.log('Changing user password');

        const response = await authenticatedFetch(`${API_BASE_URL}/password-change/`, {
            method: 'POST',
            body: JSON.stringify({
                old_password: passwordData.old_password,
                new_password: passwordData.new_password,
                new_password_confirm: passwordData.new_password_confirm
            })
        });

        const data = await response.json();

        // The server rotates the token on a password change; adopt the new one
        // so the current session keeps working.
        if (data.token) authUtils.login(data.token);

        if (onSuccess) onSuccess(data);
        return data;
    } catch (error) {
        const handledError = handleApiError(error, 'change password');
        if (onError) onError(handledError);
        throw handledError;
    }
};

/**
 * Logout user (clear session)
 * @param {Function} onSuccess - Success callback
 * @param {Function} onError - Error callback
 * @returns {Promise<boolean>} Logout success status
 */
export const logout = async (onSuccess, onError) => {
    try {
        // Call logout endpoint if available, or just clear local session
        try {
            await authenticatedFetch(`${API_BASE_URL}/logout/`, {
                method: 'POST'
            });
        } catch (error) {
            // If logout endpoint doesn't exist, just continue with local cleanup
            console.log('Logout endpoint not available, clearing local session only');
        }

        clearSession();

        if (onSuccess) onSuccess(true);
        return true;
    } catch (error) {
        // Even if server logout fails, clear local session
        clearSession();
        const handledError = handleApiError(error, 'logout');
        if (onError) onError(handledError);
        throw handledError;
    }
};
